import {Battle,SUSTAIN_RECOVERY} from './engine.mjs';
const metric=()=>({actions:{},skipped:{},adaptations:0,waits:{},reflectionDamage:0,reactionPreserved:0,spentAP:0,unusedAP:0,healing:0,overheal:0,intentSpent:0,burnConsumed:0,tideSpent:0,growthSpent:0,parasiteSpent:0,terrainSpent:0,forcedMoves:0,chillCleared:0,movement:0,hpDamage:0,shieldDamage:0,burnTaken:0,charges:{started:0,released:0,interrupted:0,rangeMiss:0,canceled:0,hpDamage:0,shieldDamage:0}});
export class RecordedBattle extends Battle{
 constructor(...args){super(...args);this.stats=[metric(),metric()];this.events=[];}
 seat(a){return a===this.player?0:1;}
 event(type,seat,data={}){if(this.events)this.events.push({type,seat,round:this.round,...data});if(this.stats&&type==='adapt')this.stats[seat].adaptations++;if(this.stats&&type==='wait')this.stats[seat].waits[data.reason]=(this.stats[seat].waits[data.reason]||0)+data.ap;}
 beginRound(){if(this.limit&&this.round>=this.limit&&!this.result){this.result='draw';this.phase='over';this.pending=null;this.log(`${this.limit} 回合已至，双方收招，本场暂未分出胜负。`,'result');return;}return super.beginRound();}
 reactionDecision(s,raw,options){const d=super.reactionDecision(s,raw,options);if(d.reason&&this.stats)this.stats[1].reactionPreserved++;return d;}
 react(kind){const r=super.react(kind);if(r.ok)this.event('reaction',0,{response:kind});return r;}
 spendTide(a,s){const n=super.spendTide(a,s);if(this.stats)this.stats[this.seat(a)].tideSpent+=n;return n;}
 moveActor(a,d,o={}){const from=this.distance;super.moveActor(a,d,o);if(this.stats&&o.forced&&this.distance!==from)this.stats[this.seat(this.other(a))].forcedMoves++;}
 clearChill(a,reason){const had=a.chilled;super.clearChill(a,reason);if(this.stats&&had&&['净息','主动移动'].includes(reason))this.stats[this.seat(a)].chillCleared++;}
 act(a,id){const s=this.skill(a,id),hp=a.hp,intent=a.intent,growth=a.growth??0,terrain=a.terrain??0,parasite=this.other(a).parasite??0,healPotential=this.healPower(a,s??{}),firstWood=a.key==='fire'&&s?.element==='wood'&&!a.woodTriggered;
  const r=super.act(a,id);if(r.ok&&this.stats){const m=this.stats[this.seat(a)];m.actions[id]=(m.actions[id]||0)+1;m.spentAP+=s.ap;m.movement+=s.kind==='move'?s.ap:0;m.healing+=Math.max(0,a.hp-hp);const potential=healPotential+(['purify','dispel'].includes(s.kind)?8:0)+(firstWood&&a.major==='sustain'?SUSTAIN_RECOVERY:0);m.overheal+=Math.max(0,potential-Math.max(0,a.hp-hp));m.intentSpent+=(s.intentCost||0)+(s.finisher?Math.min(intent,s.intentLimit??5):0);m.growthSpent+=Math.min(growth,s.consumeGrowth??0);m.parasiteSpent+=Math.min(parasite,s.consumeParasite??0);m.terrainSpent+=Math.min(terrain,s.consumeTerrain??0);if(s.kind==='charge')m.charges.started++;this.event('action',this.seat(a),{skillId:id,healing:Math.max(0,a.hp-hp)});}return r;}
 resolveAttack(a,s,raw,reduction=1,blockForce=false){const e=this.other(a),hp=e.hp,shield=e.shield,charge=e.charge,burn=e.burn;super.resolveAttack(a,s,raw,reduction,blockForce);if(this.stats){const m=this.stats[this.seat(a)],d=hp-e.hp,absorbed=shield-e.shield;m.burnConsumed+=s.id==='inferno'?burn:Math.min(burn,s.consumeBurn??0);m.hpDamage+=d;m.shieldDamage+=absorbed;this.event('hit',this.seat(a),{skillId:s.id,damage:d,shieldDamage:absorbed});if(s.kind==='charge'){m.charges.hpDamage+=d;m.charges.shieldDamage+=absorbed;}if(charge&&!e.charge&&s.interrupt)this.stats[this.seat(e)].charges.interrupted++;if(charge&&!e.charge&&s.interrupt)this.event('interrupted',this.seat(e),{skillId:charge.id});}}
 reflectHit(defender,attacker,raw){const hp=attacker.hp,shield=attacker.shield;super.reflectHit(defender,attacker,raw);if(this.stats){const m=this.stats[this.seat(defender)],damage=hp-attacker.hp,absorbed=shield-attacker.shield;m.reflectionDamage+=damage;m.hpDamage+=damage;m.shieldDamage+=absorbed;this.event('reflection',this.seat(defender),{skillId:'reflection',damage,shieldDamage:absorbed});}}
 useAnchor(a){const before=a.terrain;super.useAnchor(a);if(this.stats)this.stats[this.seat(a)].terrainSpent+=before-a.terrain;}
 tickParasite(a,raw){const owner=this.other(a),hp=a.hp,shield=a.shield;super.tickParasite(a,raw);if(this.stats){const m=this.stats[this.seat(owner)],damage=hp-a.hp,absorbed=shield-a.shield;m.hpDamage+=damage;m.shieldDamage+=absorbed;this.event('hit',this.seat(owner),{skillId:'parasite',damage,shieldDamage:absorbed});}}
 tickBurn(a){const hp=a.hp;super.tickBurn(a);if(this.stats)this.stats[this.seat(a)].burnTaken+=hp-a.hp;}
 release(a){if(this.stats){const m=this.stats[this.seat(a)].charges;if(a.charge.range.includes(this.distance))m.released++;else m.rangeMiss++;this.event(a.charge.range.includes(this.distance)?'released':'rangeMiss',this.seat(a),{skillId:a.charge.id});}return super.release(a);}
 cancelCharge(){const r=super.cancelCharge();if(r.ok&&this.stats){this.stats[0].charges.canceled++;this.event('canceled',0);}return r;}
 endTurn(){const ap=this.player.ap,r=super.endTurn();if(r.ok){if(this.stats){this.stats[0].unusedAP+=ap;if(ap)this.event('wait',0,{reason:this.playerWaitReason??'手动结束行动，保留剩余灵气。',ap});}this.playerWaitReason=null;}return r;}
 enemyStep(){const logStart=this.logs.length;const old=this.round,ap=this.enemy.ap;const r=super.enemyStep();if(this.stats){for(const l of this.logs.slice(logStart)){if(l.text.startsWith('敌方未能施展')){const reason=l.text.split('：').at(-1).replace(/。$/,'');const m=this.stats[1].skipped;m[reason]=(m[reason]||0)+1;}}if(this.round!==old||this.result==='draw')this.stats[1].unusedAP+=ap;}return r;}
 review(){return {events:structuredClone(this.events??[]),rounds:this.round,result:this.result,opponentId:this.opponentId,difficulty:this.difficulty,distance:this.distance,actors:[this.player,this.enemy].map((a,i)=>({name:a.name,key:a.key,major:a.major,hp:a.hp,maxHp:a.maxHp,...structuredClone(this.stats[i]),charges:{...this.stats[i].charges,pending:Number(Boolean(a.charge))}}))};}
}
